import asyncio
import itertools
from typing import Any, Callable, Coroutine, List, Optional


class AsyncWorkerPool:
    """An asynchronous worker pool using standard asyncio with priority queue support."""

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be non-negative")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: List[asyncio.Task] = []
        self._counter = itertools.count()
        self._is_running: bool = False
        self._is_shutting_down: bool = False

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._is_running or self._is_shutting_down:
            return
        self._is_running = True
        self._workers = [
            asyncio.create_task(self._worker_loop(), name=f"AsyncWorkerPool-Worker-{i}")
            for i in range(self.concurrency)
        ]

    async def _worker_loop(self) -> None:
        """Worker loop continuously executing tasks from the priority queue."""
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            neg_priority, count, coro_func, args, kwargs, future = item

            if future.cancelled():
                self._queue.task_done()
                continue

            try:
                result = await coro_func(*args, **kwargs)
                if not future.done():
                    future.set_result(result)
            except asyncio.CancelledError:
                if not future.done():
                    future.cancel()
                self._queue.task_done()
                raise
            except Exception as exc:
                if not future.done():
                    future.set_exception(exc)
            except BaseException as exc:
                if not future.done():
                    future.set_exception(exc)
                self._queue.task_done()
                raise
            else:
                self._queue.task_done()

    async def submit(
        self,
        coro_func: Callable[..., Coroutine[Any, Any, Any]],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        """Enqueues a coroutine function to be executed by the pool workers.

        Higher priority integers execute before lower priority integers.
        Returns an asyncio.Future that resolves with the result or exception.
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()
        item = (-priority, next(self._counter), coro_func, args, kwargs, future)

        try:
            await self._queue.put(item)
        except asyncio.CancelledError:
            if not future.done():
                future.cancel()
            raise

        return future

    async def _cancel_pending_in_queue(self) -> None:
        """Empties the queue and cancels any pending futures."""
        while not self._queue.empty():
            try:
                _, _, _, _, _, fut = self._queue.get_nowait()
                if not fut.done():
                    fut.cancel()
                self._queue.task_done()
            except asyncio.QueueEmpty:
                break

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """Shuts down the worker pool.

        - If drain=True, waits for all currently enqueued tasks to complete.
        - If drain=False, cancels all queued and currently executing tasks immediately.
        - Respects the optional timeout in seconds.
        """
        if self._is_shutting_down and not self._is_running:
            return
        self._is_shutting_down = True

        async def _do_shutdown() -> None:
            if drain:
                await self._queue.join()
            else:
                await self._cancel_pending_in_queue()

            for worker in self._workers:
                worker.cancel()

            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

        try:
            if timeout is not None:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            else:
                await _do_shutdown()
        except asyncio.TimeoutError:
            await self._cancel_pending_in_queue()
            for worker in self._workers:
                worker.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)
        finally:
            self._is_running = False
            self._workers.clear()

    async def __aenter__(self) -> "AsyncWorkerPool":
        await self.start()
        return self

    async def __aexit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        await self.shutdown(drain=True)
