from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        """Initializes cluster state with given unique node IDs."""
        self.node_ids: list[str] = list(node_ids)
        self.quorum_threshold: int = len(self.node_ids) // 2 + 1
        self._version_counter: int = 0

        # Each node maintains its own local store: key -> (version, value)
        self.stores: dict[str, dict[str, tuple[int, Any]]] = {
            node: {} for node in self.node_ids
        }

        # Map each node to its current reachable network partition (set of node IDs)
        all_nodes = set(self.node_ids)
        self.node_to_partition: dict[str, set[str]] = {
            node: all_nodes for node in self.node_ids
        }

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """Divides cluster into isolated network partitions."""
        set_a = set(group_a)
        set_b = set(group_b)
        self.node_to_partition = {}

        for node in set_a:
            self.node_to_partition[node] = set_a
        for node in set_b:
            self.node_to_partition[node] = set_b

        # Any node not in group_a or group_b becomes isolated
        for node in self.node_ids:
            if node not in self.node_to_partition:
                self.node_to_partition[node] = {node}

    def heal_partition(self) -> None:
        """Restores full connectivity and synchronizes state across all nodes."""
        all_nodes = set(self.node_ids)
        self.node_to_partition = {node: all_nodes for node in self.node_ids}

        # Reconcile latest committed state across all nodes using write versions
        latest_state: dict[str, tuple[int, Any]] = {}
        for node in self.node_ids:
            for key, entry in self.stores[node].items():
                if key not in latest_state or entry[0] > latest_state[key][0]:
                    latest_state[key] = entry

        # Apply synchronized state to every node in the cluster
        for node in self.node_ids:
            self.stores[node] = dict(latest_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """Proposes a write; commits only if from_node is in a majority partition."""
        if from_node not in self.node_to_partition:
            return False

        active_partition = self.node_to_partition[from_node]
        if len(active_partition) >= self.quorum_threshold:
            self._version_counter += 1
            for node in active_partition:
                self.stores[node][key] = (self._version_counter, value)
            return True

        return False

    def read_value(self, from_node: str, key: str) -> Any:
        """Returns the committed value for key on from_node, or None if not set."""
        if from_node not in self.stores:
            return None
        entry = self.stores[from_node].get(key)
        return entry[1] if entry is not None else None
