import re
import urllib.parse
from typing import NamedTuple


class _SQLToken(NamedTuple):
    type: str  # 'WORD', 'STRING', 'NUMBER', 'OP', 'PUNCT', 'COMMENT', 'QUOTED_IDENT', 'OBFUSCATION', etc.
    value: str
    raw: str
    pos: int


def _tokenize_sql(sql: str) -> list[_SQLToken]:
    """
    Lexes SQL text into structured tokens, differentiating code space from string literals,
    quoted identifiers, comments, and inline obfuscation artifacts.
    """
    tokens = []
    i = 0
    n = len(sql)

    while i < n:
        c = sql[i]

        if c.isspace():
            i += 1
            continue

        # MySQL Executable version comments: /*!...*/
        if sql.startswith("/*!", i):
            start = i
            end = sql.find("*/", i + 3)
            if end == -1:
                end = n
            else:
                end += 2
            tokens.append(_SQLToken("OBFUSCATION", sql[start:end], sql[start:end], start))
            i = end
            continue

        # Block comments: /*...*/
        if sql.startswith("/*", i):
            start = i
            end = sql.find("*/", i + 2)
            if end == -1:
                end = n
            else:
                end += 2
            tokens.append(_SQLToken("COMMENT", sql[start:end], sql[start:end], start))
            i = end
            continue

        # Line comments: -- or #
        if sql.startswith("--", i) or c == "#":
            start = i
            end = sql.find("\n", i)
            if end == -1:
                end = n
            tokens.append(_SQLToken("COMMENT", sql[start:end], sql[start:end], start))
            i = end
            continue

        # PostgreSQL dollar-quoted strings: $$...$$ or $tag$...$tag$
        if c == "$":
            m = re.match(r"^\$([a-zA-Z0-9_]*)\$", sql[i:])
            if m:
                tag = m.group(0)
                end_idx = sql.find(tag, i + len(tag))
                if end_idx != -1:
                    raw_str = sql[i : end_idx + len(tag)]
                    val = sql[i + len(tag) : end_idx]
                    tokens.append(_SQLToken("STRING", val, raw_str, i))
                    i = end_idx + len(tag)
                    continue

        # Single-quoted string literals: '...' (with '' and \' escape handling)
        if c == "'":
            start = i
            i += 1
            val_chars = []
            closed = False
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        val_chars.append("'")
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                elif sql[i] == "\\" and i + 1 < n:
                    val_chars.append(sql[i + 1])
                    i += 2
                else:
                    val_chars.append(sql[i])
                    i += 1
            raw_str = sql[start:i]
            val = "".join(val_chars)
            token_type = "STRING" if closed else "UNCLOSED_STRING"
            tokens.append(_SQLToken(token_type, val, raw_str, start))
            continue

        # Double-quoted identifiers / strings: "..."
        if c == '"':
            start = i
            i += 1
            val_chars = []
            closed = False
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        val_chars.append('"')
                        i += 2
                    else:
                        closed = True
                        i += 1
                        break
                elif sql[i] == "\\" and i + 1 < n:
                    val_chars.append(sql[i + 1])
                    i += 2
                else:
                    val_chars.append(sql[i])
                    i += 1
            raw_str = sql[start:i]
            val = "".join(val_chars)
            token_type = "QUOTED_IDENT" if closed else "UNCLOSED_DOUBLE_QUOTE"
            tokens.append(_SQLToken(token_type, val, raw_str, start))
            continue

        # MySQL / SQLite backtick identifiers: `...`
        if c == "`":
            start = i
            i += 1
            end = sql.find("`", i)
            if end != -1:
                val = sql[i:end]
                tokens.append(_SQLToken("QUOTED_IDENT", val, sql[start : end + 1], start))
                i = end + 1
            else:
                tokens.append(_SQLToken("UNCLOSED_BACKTICK", sql[i:], sql[start:], start))
                i = n
            continue

        # Multi-character operators (JSON extraction, comparisons, casting, etc.)
        three_char = sql[i : i + 3]
        two_char = sql[i : i + 2]
        if three_char in ("->>", "#>>"):
            tokens.append(_SQLToken("OP", three_char, three_char, i))
            i += 3
            continue
        if two_char in ("->", "#>", "::", "<=", ">=", "<>", "!=", "||", "@>", "<@"):
            tokens.append(_SQLToken("OP", two_char, two_char, i))
            i += 2
            continue

        # Single-character operators
        if c in "=<>!+-*/%&|^~@":
            tokens.append(_SQLToken("OP", c, c, i))
            i += 1
            continue

        # Punctuation
        if c in "(),;[]{}":
            tokens.append(_SQLToken("PUNCT", c, c, i))
            i += 1
            continue

        # Numeric literals (decimal, floating point, hexadecimal 0x...)
        if c.isdigit() or (c == "0" and i + 1 < n and sql[i + 1] in "xX"):
            start = i
            if sql[i : i + 2].lower() == "0x":
                i += 2
                while i < n and sql[i] in "0123456789abcdefABCDEF":
                    i += 1
            else:
                while i < n and (sql[i].isalnum() or sql[i] == "."):
                    i += 1
            num_str = sql[start:i]
            tokens.append(_SQLToken("NUMBER", num_str, num_str, start))
            continue

        # Words (Keywords and Identifiers)
        if c.isalpha() or c == "_":
            start = i
            while i < n and (sql[i].isalnum() or sql[i] == "_"):
                i += 1
            word = sql[start:i]
            tokens.append(_SQLToken("WORD", word, word, start))
            continue

        tokens.append(_SQLToken("OTHER", c, c, i))
        i += 1

    return tokens


def is_safe_sql_query(query: str) -> tuple[bool, str]:
    """
    Validates whether a SQL query string or input fragment is free from SQL injection signatures.

    Parameters:
        query (str): The SQL query string or user input to inspect.

    Returns:
        tuple[bool, str]:
            - (True, "SAFE") if the query is safe.
            - (False, "REASON") if malicious SQL injection patterns are detected.
    """
    if not isinstance(query, str) or not query.strip():
        return True, "SAFE"

    # 1. URL decoding and multi-representation normalization
    try:
        decoded_query = urllib.parse.unquote(query)
    except Exception:
        decoded_query = query

    candidates = [query]
    if decoded_query != query:
        candidates.append(decoded_query)

    for q in candidates:
        # Null byte injection / obfuscation
        if "\x00" in q or "%00" in q.lower():
            return False, "Detected obfuscation / null byte evasion"

        # MySQL conditional execution comments: e.g. /*!50000SELECT*/, /*!SELECT*/
        if re.search(r"/\*!\s*\d*", q, re.IGNORECASE):
            return False, "Detected obfuscation / inline comment evasion: MySQL executable comment syntax"

        # Inline comments splitting tokens: e.g. UN/**/ION, SE/**/LECT, pg_/**/sleep
        if re.search(r"[a-zA-Z0-9_]\s*/\*.*?\*/\s*[a-zA-Z0-9_]", q, re.DOTALL):
            return False, "Detected obfuscation / inline comment evasion: inline comment inside token"

        # CHAR/CHR encoding obfuscation: e.g. CHAR(117, 110, 105, 111, 110)
        if re.search(r"\b(?:CHAR|CHR)\s*\(\s*\d+(?:\s*,\s*\d+)*\s*\)", q, re.IGNORECASE):
            return False, "Detected obfuscation: CHAR/CHR function evasion"

        # Quote breakout followed by comments: e.g. admin'--, admin' --, admin' #, admin'/*, admin") --
        if re.search(r"""^[^'"]*['"]\s*\)*\s*(?:--|#|/\*)""", q):
            return False, "Detected boolean/tautology SQL injection: quote followed by comment"

        # Leading quote logical breakout: e.g. ' OR '1'='1', " OR 1=1 --, ') OR ('x'='x
        if re.search(r"""^\s*['"]\s*\)*\s*(?:OR|AND)\b""", q, re.IGNORECASE):
            return False, "Detected boolean/tautology SQL injection: leading quote logical breakout"

        # Direct tautology breakout patterns
        if re.search(r"""['"]\s*\)*\s*OR\s*\(?\s*['"]?(\w+)['"]?\s*=\s*['"]?\1['"]?""", q, re.IGNORECASE):
            return False, "Detected boolean/tautology SQL injection: quote breakout OR tautology"

        if re.search(r"""['"]\s*\)*\s*OR\s*\(?\s*['"]\s*=\s*['"]""", q, re.IGNORECASE):
            return False, "Detected boolean/tautology SQL injection: quote breakout OR tautology"

        if re.search(r"""['"]\s*\)*\s*OR\s*\(?\s*(?:TRUE|1)\b""", q, re.IGNORECASE):
            return False, "Detected boolean/tautology SQL injection: quote breakout OR tautology"

    # 2. Tokenize SQL to perform syntactic and structural security inspection
    tokens = _tokenize_sql(query)

    # Check unclosed/dangling quoted fragments containing SQL keywords or comment syntax
    for tok in tokens:
        if tok.type in ("UNCLOSED_STRING", "UNCLOSED_DOUBLE_QUOTE", "UNCLOSED_BACKTICK"):
            if re.search(r"(?:--|#|/\*|\bOR\b|\bAND\b|\bUNION\b|;)", tok.value, re.IGNORECASE):
                return False, "Detected malicious syntax in unclosed/dangling quoted fragment"

    n_tok = len(tokens)
    for idx, tok in enumerate(tokens):
        # Obfuscation tokens
        if tok.type == "OBFUSCATION":
            return False, "Detected obfuscation / inline comment evasion"

        # Evasion by splitting keywords across inline comments (e.g. UN/**/ION)
        if tok.type == "COMMENT" and 0 < idx < n_tok - 1:
            prev_tok = tokens[idx - 1]
            next_tok = tokens[idx + 1]
            if prev_tok.type == "WORD" and next_tok.type == "WORD":
                combined = (prev_tok.value + next_tok.value).upper()
                if combined in (
                    "UNION",
                    "SELECT",
                    "DELETE",
                    "DROP",
                    "INSERT",
                    "UPDATE",
                    "EXEC",
                    "EXECUTE",
                    "SLEEP",
                    "BENCHMARK",
                ):
                    return False, f"Detected obfuscation / inline comment evasion: {combined}"

        # Stacked query execution: ';' followed by DDL/DML/Admin operations
        if tok.type == "PUNCT" and tok.value == ";":
            next_idx = idx + 1
            while next_idx < n_tok and tokens[next_idx].type == "COMMENT":
                next_idx += 1
            if next_idx < n_tok:
                next_tok = tokens[next_idx]
                if next_tok.type == "WORD" and next_tok.value.upper() in (
                    "DROP",
                    "DELETE",
                    "TRUNCATE",
                    "ALTER",
                    "CREATE",
                    "INSERT",
                    "UPDATE",
                    "EXEC",
                    "EXECUTE",
                    "SHUTDOWN",
                    "GRANT",
                    "REVOKE",
                    "DECLARE",
                    "CALL",
                ):
                    return False, f"Detected stacked query execution: ; {next_tok.value.upper()}"

        # Standalone system procedure execution: EXEC xp_cmdshell, sp_executesql, etc.
        if tok.type == "WORD" and tok.value.upper() in ("EXEC", "EXECUTE"):
            next_idx = idx + 1
            while next_idx < n_tok and tokens[next_idx].type == "COMMENT":
                next_idx += 1
            if next_idx < n_tok and tokens[next_idx].type == "WORD":
                proc_name = tokens[next_idx].value.lower()
                if proc_name.startswith(("xp_", "sp_", "master.")):
                    return False, f"Detected stacked query execution: EXEC {proc_name}"

        # UNION-based data exfiltration: UNION SELECT, UNION ALL SELECT, UNION (SELECT ...)
        if tok.type == "WORD" and tok.value.upper() == "UNION":
            lookahead_idx = idx + 1
            while lookahead_idx < n_tok and tokens[lookahead_idx].type == "COMMENT":
                lookahead_idx += 1
            if lookahead_idx < n_tok:
                t1 = tokens[lookahead_idx]
                if t1.type == "WORD" and t1.value.upper() in ("ALL", "DISTINCT"):
                    lookahead_idx += 1
                    while lookahead_idx < n_tok and tokens[lookahead_idx].type == "COMMENT":
                        lookahead_idx += 1
                if lookahead_idx < n_tok:
                    t2 = tokens[lookahead_idx]
                    if (t2.type == "WORD" and t2.value.upper() == "SELECT") or (
                        t2.type == "PUNCT" and t2.value == "("
                    ):
                        return False, "Detected UNION-based data exfiltration: UNION SELECT"

        # Time-based blind execution functions
        if tok.type == "WORD":
            w_lower = tok.value.lower()
            w_upper = tok.value.upper()

            # pg_sleep(...)
            if w_lower == "pg_sleep":
                next_idx = idx + 1
                while next_idx < n_tok and tokens[next_idx].type == "COMMENT":
                    next_idx += 1
                if next_idx < n_tok and tokens[next_idx].type == "PUNCT" and tokens[next_idx].value == "(":
                    return False, "Detected time-based blind SQL injection: pg_sleep()"

            # BENCHMARK(...)
            if w_upper == "BENCHMARK":
                next_idx = idx + 1
                while next_idx < n_tok and tokens[next_idx].type == "COMMENT":
                    next_idx += 1
                if next_idx < n_tok and tokens[next_idx].type == "PUNCT" and tokens[next_idx].value == "(":
                    return False, "Detected time-based blind SQL injection: BENCHMARK()"

            # SLEEP(...)
            if w_upper == "SLEEP":
                next_idx = idx + 1
                while next_idx < n_tok and tokens[next_idx].type == "COMMENT":
                    next_idx += 1
                if next_idx < n_tok and tokens[next_idx].type == "PUNCT" and tokens[next_idx].value == "(":
                    return False, "Detected time-based blind SQL injection: SLEEP()"

            # WAITFOR DELAY / WAITFOR TIME
            if w_upper == "WAITFOR":
                next_idx = idx + 1
                while next_idx < n_tok and tokens[next_idx].type == "COMMENT":
                    next_idx += 1
                if (
                    next_idx < n_tok
                    and tokens[next_idx].type == "WORD"
                    and tokens[next_idx].value.upper() in ("DELAY", "TIME")
                ):
                    return (
                        False,
                        f"Detected time-based blind SQL injection: WAITFOR {tokens[next_idx].value.upper()}",
                    )

            # DBMS_PIPE.RECEIVE_MESSAGE or DBMS_LOCK.SLEEP
            if w_lower in ("dbms_pipe", "dbms_lock") and idx + 2 < n_tok:
                if tokens[idx + 1].type == "OP" and tokens[idx + 1].value == "." and tokens[idx + 2].type == "WORD":
                    sub_func = tokens[idx + 2].value.lower()
                    if sub_func in ("receive_message", "sleep"):
                        return False, f"Detected time-based blind SQL injection: {w_lower}.{sub_func}"

        # Boolean / Tautology injection outside string literals
        if tok.type == "WORD" and tok.value.upper() in ("OR", "AND"):
            sub_toks = []
            k = idx + 1
            # Skip opening parentheses if present (e.g. OR (1=1))
            while k < n_tok and tokens[k].type == "PUNCT" and tokens[k].value == "(":
                k += 1

            while k < n_tok and len(sub_toks) < 3:
                if tokens[k].type != "COMMENT":
                    sub_toks.append(tokens[k])
                k += 1

            # Check literal tautology comparisons: e.g. '1'='1', 1=1, 'a'='a', 1!=2
            if len(sub_toks) == 3:
                lhs, op, rhs = sub_toks
                if op.type == "OP" and op.value in ("=", "==", "<>", "!="):
                    if lhs.type in ("STRING", "NUMBER") and rhs.type in ("STRING", "NUMBER"):
                        if op.value in ("=", "==") and lhs.value == rhs.value:
                            return (
                                False,
                                f"Detected boolean/tautology SQL injection: {tok.value.upper()} {lhs.value} = {rhs.value}",
                            )
                        if op.value in ("<>", "!=") and lhs.value != rhs.value:
                            return (
                                False,
                                f"Detected boolean/tautology SQL injection: {tok.value.upper()} {lhs.value} != {rhs.value}",
                            )
                    elif lhs.type == "WORD" and rhs.type == "WORD":
                        if lhs.value.lower() in ("true", "false") and rhs.value.lower() in ("true", "false"):
                            if op.value in ("=", "==") and lhs.value.lower() == rhs.value.lower():
                                return (
                                    False,
                                    f"Detected boolean/tautology SQL injection: {tok.value.upper()} {lhs.value} = {rhs.value}",
                                )

            # Standalone OR TRUE / OR 1 tautology
            if tok.value.upper() == "OR" and len(sub_toks) >= 1:
                first = sub_toks[0]
                if first.type == "WORD" and first.value.upper() == "TRUE":
                    return False, "Detected boolean/tautology SQL injection: OR TRUE"
                if first.type == "NUMBER" and first.value == "1" and (
                    len(sub_toks) == 1
                    or (len(sub_toks) > 1 and sub_toks[1].type not in ("OP", "WORD"))
                ):
                    return False, "Detected boolean/tautology SQL injection: OR 1"

    return True, "SAFE"
