import ast
import re


def _extract_names_from_str(s: str) -> set[str]:
    """Extract identifier names from a string (e.g., forward-referenced type annotations)."""
    try:
        t = ast.parse(s, mode="eval")
        return {n.id for n in ast.walk(t) if isinstance(n, ast.Name)}
    except Exception:
        return set(re.findall(r"\b[a-zA-Z_][a-zA-Z0-9_]*\b", s))


def _extract_names_from_annotation(node: ast.AST | None) -> set[str]:
    """Recursively extract identifiers from type annotations, including string literals."""
    if node is None:
        return set()
    names = set()
    for sub in ast.walk(node):
        if isinstance(sub, ast.Name):
            names.add(sub.id)
        elif isinstance(sub, ast.Constant) and isinstance(sub.value, str):
            names.update(_extract_names_from_str(sub.value))
    return names


def _extract_references_from_node(node: ast.AST) -> set[str]:
    """Extract all referenced identifiers, type annotations, and exported names from an AST node."""
    names = set()
    for subnode in ast.walk(node):
        if isinstance(subnode, ast.Name):
            names.add(subnode.id)
        elif isinstance(subnode, (ast.Global, ast.Nonlocal)):
            names.update(subnode.names)
        elif isinstance(subnode, ast.Assign):
            for target in subnode.targets:
                if isinstance(target, ast.Name) and target.id == "__all__":
                    for elt in ast.walk(subnode.value):
                        if isinstance(elt, ast.Constant) and isinstance(
                            elt.value, str
                        ):
                            names.add(elt.value)
        elif isinstance(subnode, ast.AugAssign):
            if (
                isinstance(subnode.target, ast.Name)
                and subnode.target.id == "__all__"
            ):
                for elt in ast.walk(subnode.value):
                    if isinstance(elt, ast.Constant) and isinstance(
                        elt.value, str
                    ):
                        names.add(elt.value)
        elif isinstance(subnode, ast.Call):
            if (
                isinstance(subnode.func, ast.Attribute)
                and isinstance(subnode.func.value, ast.Name)
                and subnode.func.value.id == "__all__"
            ):
                for arg in subnode.args:
                    for elt in ast.walk(arg):
                        if isinstance(elt, ast.Constant) and isinstance(
                            elt.value, str
                        ):
                            names.add(elt.value)
        elif isinstance(subnode, ast.AnnAssign):
            names.update(_extract_names_from_annotation(subnode.annotation))
        elif isinstance(subnode, ast.arg):
            names.update(_extract_names_from_annotation(subnode.annotation))
        elif isinstance(subnode, (ast.FunctionDef, ast.AsyncFunctionDef)):
            names.update(_extract_names_from_annotation(subnode.returns))

        if hasattr(subnode, "type_comment") and isinstance(
            subnode.type_comment, str
        ):
            names.update(_extract_names_from_str(subnode.type_comment))

    return names


def prune_dead_code_and_imports(source_code: str) -> str:
    """Prunes unused imports and dead top-level private functions from Python source code.

    Preserves module docstrings, class definitions, global variables, public
    functions, and __future__ imports. Returns syntactically valid refactored
    code.
    """
    tree = ast.parse(source_code, type_comments=True)

    # Separate top-level statements into private functions, imports, and live roots
    private_funcs: dict[str, list[ast.AST]] = {}
    roots: list[ast.AST] = []

    for stmt in tree.body:
        if isinstance(
            stmt, (ast.FunctionDef, ast.AsyncFunctionDef)
        ) and stmt.name.startswith("_"):
            private_funcs.setdefault(stmt.name, []).append(stmt)
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            pass
        else:
            roots.append(stmt)

    # Collect initial active names from roots (public functions, classes, globals, docstrings, etc.)
    visited_names: set[str] = set()
    for root in roots:
        visited_names.update(_extract_references_from_node(root))

    # Breadth-first reachability search to find reachable private functions and their dependencies
    queue = list(visited_names)
    reachable_private_funcs: set[ast.AST] = set()

    while queue:
        name = queue.pop()
        if name in private_funcs:
            for fn in private_funcs[name]:
                if fn not in reachable_private_funcs:
                    reachable_private_funcs.add(fn)
                    fn_refs = _extract_references_from_node(fn)
                    new_refs = fn_refs - visited_names
                    visited_names.update(new_refs)
                    queue.extend(new_refs)

    # Reconstruct top-level statements: prune dead private functions and unused imports
    new_body: list[ast.AST] = []
    for stmt in tree.body:
        if isinstance(
            stmt, (ast.FunctionDef, ast.AsyncFunctionDef)
        ) and stmt.name.startswith("_"):
            if stmt in reachable_private_funcs:
                new_body.append(stmt)
        elif isinstance(stmt, ast.Import):
            kept_aliases = []
            for alias in stmt.names:
                bound_name = (
                    alias.asname
                    if alias.asname
                    else alias.name.split(".", 1)[0]
                )
                if bound_name in visited_names:
                    kept_aliases.append(alias)
            if kept_aliases:
                stmt.names = kept_aliases
                new_body.append(stmt)
        elif isinstance(stmt, ast.ImportFrom):
            if stmt.module == "__future__":
                new_body.append(stmt)
            else:
                kept_aliases = []
                for alias in stmt.names:
                    if alias.name == "*":
                        kept_aliases.append(alias)
                    else:
                        bound_name = (
                            alias.asname if alias.asname else alias.name
                        )
                        if bound_name in visited_names:
                            kept_aliases.append(alias)
                if kept_aliases:
                    stmt.names = kept_aliases
                    new_body.append(stmt)
        else:
            new_body.append(stmt)

    tree.body = new_body
    refactored_code = ast.unparse(tree)
    compile(refactored_code, "<refactored>", "exec")
    return refactored_code
