import threading
import time
from collections import deque
from typing import Deque, Dict, Optional


class SlidingWindowRateLimiter:
    """Thread-safe sliding window rate limiter implementation."""

    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests < 0:
            raise ValueError("max_requests must be a non-negative integer")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._requests: Dict[str, Deque[float]] = {}
        self._lock = threading.Lock()

    def _cleanup(self, key: str, now: float) -> None:
        """Remove timestamps outside the current sliding window."""
        cutoff = now - self.window_seconds
        if key in self._requests:
            dq = self._requests[key]
            while dq and dq[0] <= cutoff:
                dq.popleft()
            if not dq:
                del self._requests[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        """
        Check if a request is allowed for the given key.

        Returns:
            (True, 0.0) if allowed.
            (False, retry_after_seconds) if rate limited.
        """
        now = time.time() if timestamp is None else float(timestamp)

        with self._lock:
            self._cleanup(key, now)
            dq = self._requests.get(key)
            current_count = len(dq) if dq is not None else 0

            if current_count < self.max_requests:
                if dq is None:
                    dq = deque()
                    self._requests[key] = dq
                dq.append(now)
                return (True, 0.0)
            else:
                if dq and len(dq) > 0:
                    oldest_ts = dq[0]
                    retry_after = max(0.0, (oldest_ts + self.window_seconds) - now)
                else:
                    retry_after = float(self.window_seconds)
                return (False, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        """Return the number of remaining available requests in the sliding window."""
        now = time.time() if timestamp is None else float(timestamp)

        with self._lock:
            self._cleanup(key, now)
            dq = self._requests.get(key)
            current_count = len(dq) if dq is not None else 0
            return max(0, self.max_requests - current_count)
