import asyncio
from typing import Any, Callable, List, Optional


class _WorkItem:
    __slots__ = ("priority", "count", "future", "coro_func", "args", "kwargs", "is_sentinel")

    def __init__(
        self,
        priority: int = 0,
        count: int = 0,
        future: Optional[asyncio.Future] = None,
        coro_func: Any = None,
        args: tuple = (),
        kwargs: Optional[dict] = None,
        is_sentinel: bool = False,
    ):
        self.priority = priority
        self.count = count
        self.future = future
        self.coro_func = coro_func
        self.args = args
        self.kwargs = kwargs or {}
        self.is_sentinel = is_sentinel

    def __lt__(self, other: "_WorkItem") -> bool:
        if self.is_sentinel != other.is_sentinel:
            return not self.is_sentinel  # non-sentinel items execute before sentinels
        if self.priority != other.priority:
            return self.priority > other.priority  # higher priority integer executes first
        return self.count < other.count  # FIFO tie-breaking for equal priority items


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency <= 0:
            raise ValueError("Concurrency must be greater than 0")
        if max_queue_size <= 0:
            raise ValueError("Max queue size must be greater than 0")

        self.concurrency = concurrency
        self.max_queue_size = max_queue_size
        self._queue: asyncio.PriorityQueue[_WorkItem] = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: List[asyncio.Task] = []
        self._counter: int = 0
        self._running: bool = False
        self._is_shutting_down: bool = False

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._running:
            return
        self._running = True
        self._is_shutting_down = False
        self._workers = [
            asyncio.create_task(self._worker_loop(), name=f"AsyncWorkerPool-worker-{i}")
            for i in range(self.concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        """Enqueues a coroutine function to be executed by pool workers.

        Returns an asyncio.Future that resolves with the result (or exception).
        """
        if self._is_shutting_down or not self._running:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()

        self._counter += 1
        item = _WorkItem(
            priority=priority,
            count=self._counter,
            future=future,
            coro_func=coro_func,
            args=args,
            kwargs=kwargs,
        )

        try:
            await self._queue.put(item)
        except Exception:
            if self._is_shutting_down:
                raise RuntimeError("Pool is shutting down")
            raise

        if self._is_shutting_down:
            if not future.done():
                future.cancel()
            raise RuntimeError("Pool is shutting down")

        return future

    async def _worker_loop(self) -> None:
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            if item.is_sentinel:
                self._queue.task_done()
                break

            future = item.future
            if future is None or future.cancelled():
                self._queue.task_done()
                continue

            task = asyncio.create_task(item.coro_func(*item.args, **item.kwargs))
            user_cancelled = False

            def _on_future_cancelled(f: asyncio.Future) -> None:
                nonlocal user_cancelled
                if f.cancelled() and not task.done():
                    user_cancelled = True
                    task.cancel()

            if not future.done():
                future.add_done_callback(_on_future_cancelled)

            try:
                res = await task
                if not future.done():
                    future.set_result(res)
            except asyncio.CancelledError:
                if user_cancelled:
                    if not future.done():
                        future.cancel()
                else:
                    # Worker task itself was cancelled during pool shutdown
                    if not task.done():
                        task.cancel()
                    if not future.done():
                        future.cancel()
                    self._queue.task_done()
                    raise
            except Exception as exc:
                if not future.done():
                    future.set_exception(exc)
            finally:
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """Shuts down the pool.

        If drain=True, waits for enqueued tasks to complete.
        If drain=False, cancels all queued and executing tasks immediately.
        Respects optional timeout in seconds.
        """
        if self._is_shutting_down or not self._running:
            return
        self._is_shutting_down = True

        async def _cleanup_queue() -> None:
            while not self._queue.empty():
                try:
                    item = self._queue.get_nowait()
                    if not item.is_sentinel and item.future and not item.future.done():
                        item.future.cancel()
                    self._queue.task_done()
                except asyncio.QueueEmpty:
                    break

        async def _do_shutdown() -> None:
            if drain:
                await self._queue.join()
                for _ in range(self.concurrency):
                    await self._queue.put(_WorkItem(is_sentinel=True))
                await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                await _cleanup_queue()
                for worker in self._workers:
                    worker.cancel()
                await asyncio.gather(*self._workers, return_exceptions=True)

        try:
            if timeout is not None:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            else:
                await _do_shutdown()
        except asyncio.TimeoutError:
            await _cleanup_queue()
            for worker in self._workers:
                worker.cancel()
            await asyncio.gather(*self._workers, return_exceptions=True)
        finally:
            self._running = False
            self._is_shutting_down = False
            self._workers.clear()
