from typing import Any, Optional


class QuorumCluster:
    """Coordinates distributed consensus across a cluster of N nodes using quorum rules."""

    def __init__(self, node_ids: list[str]) -> None:
        self.node_ids: list[str] = list(node_ids)
        self.n: int = len(self.node_ids)
        self.quorum_threshold: int = (self.n // 2) + 1
        # Stores key -> (value, commit_sequence) for each node
        self._nodes: dict[str, dict[str, tuple[Any, int]]] = {
            node_id: {} for node_id in self.node_ids
        }
        self._partitions: Optional[list[set[str]]] = None
        self._commit_seq: int = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """Divides cluster into isolated network partitions."""
        set_a = set(group_a)
        set_b = set(group_b)
        self._partitions = [set_a, set_b]
        assigned = set_a | set_b
        for node_id in self.node_ids:
            if node_id not in assigned:
                self._partitions.append({node_id})

    def heal_partition(self) -> None:
        """Restores full connectivity and synchronizes committed state across all nodes."""
        self._partitions = None
        all_keys: set[str] = set()
        for store in self._nodes.values():
            all_keys.update(store.keys())

        # Synchronize latest committed state for each key across all nodes
        for key in all_keys:
            best_val = None
            best_ver = -1
            for store in self._nodes.values():
                if key in store:
                    val, ver = store[key]
                    if ver > best_ver:
                        best_ver = ver
                        best_val = val
            if best_ver != -1:
                for store in self._nodes.values():
                    store[key] = (best_val, best_ver)

    def _get_active_partition(self, node_id: str) -> set[str]:
        """Returns the set of node IDs accessible from the given node."""
        if self._partitions is None:
            return set(self.node_ids)
        for part in self._partitions:
            if node_id in part:
                return part
        return {node_id}

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """Proposes a write from from_node.

        Commits if from_node belongs to a partition having a strict majority (>= quorum threshold).
        """
        if from_node not in self._nodes:
            return False

        partition_nodes = self._get_active_partition(from_node)
        if len(partition_nodes) < self.quorum_threshold:
            return False

        self._commit_seq += 1
        for node_id in partition_nodes:
            if node_id in self._nodes:
                self._nodes[node_id][key] = (value, self._commit_seq)
        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """Returns the committed value for key on from_node (or None if not set)."""
        if from_node in self._nodes and key in self._nodes[from_node]:
            return self._nodes[from_node][key][0]
        return None
