```python
import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    """
    Refactors Python source code by pruning unused imports and unused top-level private functions.

    - Unused `import` and `from ... import ...` aliases/statements are pruned.
    - Top-level functions starting with `_` are removed if unreferenced outside their definition.
    - Preserves module docstrings, class definitions, global assignments, and public functions.
    - Ensures returned Python code is valid and compiles via `compile()`.
    """
    tree = ast.parse(source_code)

    def get_bound_name(alias: ast.alias) -> str:
        if alias.asname:
            return alias.asname
        return alias.name.split(".")[0]

    def get_referenced_names_in_node(node: ast.AST) -> set[str]:
        names = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                names.add(child.id)
            elif isinstance(child, (ast.Assign, ast.AnnAssign)):
                target_names = set()
                targets = [child.target] if isinstance(child, ast.AnnAssign) else child.targets
                for t in targets:
                    if isinstance(t, ast.Name) and t.id == "__all__":
                        target_names.add("__all__")
                if "__all__" in target_names and child.value:
                    for v in ast.walk(child.value):
                        if isinstance(v, ast.Constant) and isinstance(v.value, str):
                            names.add(v.value)
        return names

    # Track non-empty statement lists to preserve block syntax validity if statements are removed
    non_empty_lists = set()
    for node in ast.walk(tree):
        for attr in ("body", "orelse", "finalbody"):
            if hasattr(node, attr):
                lst = getattr(node, attr)
                if isinstance(lst, list) and len(lst) > 0:
                    non_empty_lists.add(id(lst))

    # Map top-level private functions by name
    top_private_funcs = {}
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            top_private_funcs[stmt.name] = stmt

    # Determine reachable code roots (public functions, classes, global assigns, expressions, etc.)
    reachable_names = set()
    queue = []

    for stmt in tree.body:
        if isinstance(stmt, (ast.Import, ast.ImportFrom)):
            continue
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            continue
        queue.append(stmt)

    visited_nodes = set()
    while queue:
        curr = queue.pop()
        if id(curr) in visited_nodes:
            continue
        visited_nodes.add(id(curr))

        refs = get_referenced_names_in_node(curr)
        reachable_names.update(refs)

        for name in refs:
            if name in top_private_funcs and id(top_private_funcs[name]) not in visited_nodes:
                queue.append(top_private_funcs[name])

    # Transform AST to remove unused imports and dead top-level private functions
    class RefactoringTransformer(ast.NodeTransformer):
        def visit_Import(self, node: ast.Import):
            new_aliases = [
                alias
                for alias in node.names
                if get_bound_name(alias) == "*" or get_bound_name(alias) in reachable_names
            ]
            if not new_aliases:
                return None
            node.names = new_aliases
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom):
            new_aliases = [
                alias
                for alias in node.names
                if get_bound_name(alias) == "*" or get_bound_name(alias) in reachable_names
            ]
            if not new_aliases:
                return None
            node.names = new_aliases
            return node

        def visit_FunctionDef(self, node: ast.FunctionDef):
            if node in tree.body and node.name.startswith("_") and node.name not in reachable_names:
                return None
            self.generic_visit(node)
            return node

        def visit_AsyncFunctionDef(self, node: ast.AsyncFunctionDef):
            if node in tree.body and node.name.startswith("_") and node.name not in reachable_names:
                return None
            self.generic_visit(node)
            return node

    transformer = RefactoringTransformer()
    new_tree = transformer.visit(tree)

    # Ensure statement blocks that became empty receive `pass` to maintain syntax validity
    for node in ast.walk(new_tree):
        if isinstance(node, ast.Module):
            continue
        for attr in ("body", "orelse", "finalbody"):
            if hasattr(node, attr):
                lst = getattr(node, attr)
                if isinstance(lst, list):
                    if len(lst) == 0 and (attr == "body" or id(lst) in non_empty_lists):
                        setattr(node, attr, [ast.Pass()])

    ast.fix_missing_locations(new_tree)
    result_code = ast.unparse(new_tree)
    compile(result_code, "<string>", "exec")
    return result_code
