import time
import threading
from typing import Optional, Dict
from collections import deque

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._lock = threading.Lock()
        self._requests: Dict[str, deque] = {}

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self._lock:
            if key not in self._requests:
                self._requests[key] = deque()

            history = self._requests[key]
            cutoff = timestamp - self.window_seconds

            # Clean up requests that are outside the sliding window
            while history and history[0] <= cutoff:
                history.popleft()

            if len(history) < self.max_requests:
                history.append(timestamp)
                return True, 0.0
            else:
                if not history:
                    # Fallback in case max_requests is 0 or negative
                    return False, self.window_seconds

                # The oldest request inside the window will expire at oldest_timestamp + window_seconds
                oldest_timestamp = history[0]
                retry_after = (oldest_timestamp + self.window_seconds) - timestamp
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self._lock:
            if key not in self._requests:
                return max(0, self.max_requests)

            history = self._requests[key]
            cutoff = timestamp - self.window_seconds

            # Clean up requests that are outside the sliding window
            while history and history[0] <= cutoff:
                history.popleft()

            return max(0, self.max_requests - len(history))
