class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids). Quorum threshold is N // 2 + 1.
        """
        self.node_ids = list(node_ids)
        self.quorum = len(self.node_ids) // 2 + 1

        # Maps node_id -> key -> (value, version)
        self.nodes_state = {node_id: {} for node_id in self.node_ids}

        # Maps node_id -> set of reachable node_ids
        self.partitions = {node_id: set(self.node_ids) for node_id in self.node_ids}

        # Global logical version counter to track order of committed writes
        self.current_version = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        Nodes not in either group are isolated in their own partition.
        """
        set_a = set(group_a)
        set_b = set(group_b)

        for node in self.node_ids:
            if node in set_a:
                self.partitions[node] = set_a
            elif node in set_b:
                self.partitions[node] = set_b
            else:
                self.partitions[node] = {node}

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        # Restore full connectivity
        all_nodes_set = set(self.node_ids)
        for node in self.node_ids:
            self.partitions[node] = all_nodes_set

        # Synchronize committed state: for each key, propagate the value
        # with the highest version (latest committed) to all nodes.
        all_keys = set()
        for state in self.nodes_state.values():
            all_keys.update(state.keys())

        for key in all_keys:
            max_version = -1
            latest_value = None
            for state in self.nodes_state.values():
                if key in state:
                    val, ver = state[key]
                    if ver > max_version:
                        max_version = ver
                        latest_value = val

            if max_version != -1:
                for node in self.node_ids:
                    self.nodes_state[node][key] = (latest_value, max_version)

    def propose_write(self, from_node: str, key: str, value: any) -> bool:
        """
        Proposes a write from from_node.
        If from_node belongs to a partition having a STRICT MAJORITY, the write
        commits, updates state in all nodes within that partition, and returns True.
        Otherwise, the write is REJECTED and returns False.
        """
        if from_node not in self.partitions:
            return False

        active_partition = self.partitions[from_node]
        if len(active_partition) >= self.quorum:
            self.current_version += 1
            for node in active_partition:
                self.nodes_state[node][key] = (value, self.current_version)
            return True

        return False

    def read_value(self, from_node: str, key: str) -> any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node in self.nodes_state and key in self.nodes_state[from_node]:
            return self.nodes_state[from_node][key][0]
        return None
