import base64
import json
import hmac
import hashlib
import time

def verify_jwt(token: str, secret_key: str, allowed_algs: list[str] = ["HS256"]) -> dict:
    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    # Helper to handle base64url decoding with dynamic padding
    def decode_base64url(s: str) -> bytes:
        rem = len(s) % 4
        if rem > 0:
            s += "=" * (4 - rem)
        try:
            return base64.urlsafe_b64decode(s)
        except Exception as e:
            raise ValueError("Invalid base64url encoding") from e

    try:
        header_raw = decode_base64url(parts[0])
        header = json.loads(header_raw)
    except Exception as e:
        raise ValueError("Invalid header structure") from e

    try:
        payload_raw = decode_base64url(parts[1])
        payload = json.loads(payload_raw)
    except Exception as e:
        raise ValueError("Invalid payload structure") from e

    # Strictly validate alg against allowed_algs and explicitly reject 'none'
    alg = header.get("alg")
    if not alg or alg not in allowed_algs or alg == "none":
        raise ValueError("Algorithm not allowed")

    # Strictly validate expiration
    now = time.time()
    if "exp" in payload:
        exp = payload["exp"]
        if not isinstance(exp, (int, float)):
            raise ValueError("Invalid expiration format")
        if exp <= now:
            raise ValueError("Token expired")

    # Decode signature
    try:
        signature = decode_base64url(parts[2])
    except Exception as e:
        raise ValueError("Invalid signature encoding") from e

    # Map algorithm to corresponding hashing function
    if alg == "HS256":
        digestmod = hashlib.sha256
    elif alg == "HS384":
        digestmod = hashlib.sha384
    elif alg == "HS512":
        digestmod = hashlib.sha512
    else:
        raise ValueError("Unsupported algorithm")

    # Verify HMAC signature securely
    signing_input = f"{parts[0]}.{parts[1]}".encode("utf-8")
    expected_sig = hmac.new(secret_key.encode("utf-8"), signing_input, digestmod).digest()

    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    return payload
