def is_safe_sql_query(query: str) -> tuple[bool, str]:
    def tokenize_sql(q: str):
        tokens = []
        i = 0
        n = len(q)
        while i < n:
            # Check C-style comments
            if q[i:i+2] == '/*':
                start = i
                i += 2
                closed = False
                while i < n - 1:
                    if q[i:i+2] == '*/':
                        i += 2
                        closed = True
                        break
                    i += 1
                if not closed:
                    i = n
                tokens.append(('COMMENT_C', q[start:i], start, i))
                continue

            # Check dash comments
            if q[i:i+2] == '--':
                start = i
                i += 2
                while i < n and q[i] != '\n':
                    i += 1
                tokens.append(('COMMENT_LINE', q[start:i], start, i))
                continue

            # Check hash comments (MySQL style)
            if q[i] == '#':
                start = i
                i += 1
                while i < n and q[i] != '\n':
                    i += 1
                tokens.append(('COMMENT_LINE', q[start:i], start, i))
                continue

            # Check Dollar-quoted strings (PostgreSQL: $tag$...$tag$)
            if q[i] == '$':
                j = i + 1
                while j < n and (q[j].isalnum() or q[j] == '_'):
                    j += 1
                if j < n and q[j] == '$':
                    tag = q[i:j+1]
                    start = i
                    i = j + 1
                    closed = False
                    len_tag = len(tag)
                    while i <= n - len_tag:
                        if q[i:i+len_tag] == tag:
                            i += len_tag
                            closed = True
                            break
                        i += 1
                    if not closed:
                        i = n
                    tokens.append(('STRING_DOLLAR', q[start:i], start, i))
                    continue

            # Check Single Quoted Strings
            if q[i] == "'":
                start = i
                i += 1
                while i < n:
                    if q[i] == "'":
                        if i + 1 < n and q[i+1] == "'":
                            i += 2
                        else:
                            i += 1
                            break
                    elif q[i] == '\\':
                        i += 2
                    else:
                        i += 1
                tokens.append(('STRING_SINGLE', q[start:i], start, i))
                continue

            # Check Double Quoted Strings
            if q[i] == '"':
                start = i
                i += 1
                while i < n:
                    if q[i] == '"':
                        if i + 1 < n and q[i+1] == '"':
                            i += 2
                        else:
                            i += 1
                            break
                    elif q[i] == '\\':
                        i += 2
                    else:
                        i += 1
                tokens.append(('STRING_DOUBLE', q[start:i], start, i))
                continue

            # Check Backticks (MySQL identifier)
            if q[i] == '`':
                start = i
                i += 1
                while i < n:
                    if q[i] == '`':
                        if i + 1 < n and q[i+1] == '`':
                            i += 2
                        else:
                            i += 1
                            break
                    elif q[i] == '\\':
                        i += 2
                    else:
                        i += 1
                tokens.append(('IDENTIFIER_BACKTICK', q[start:i], start, i))
                continue

            # Check Operators
            if q[i:i+3] == '->>':
                tokens.append(('OPERATOR', '->>', i, i+3))
                i += 3
                continue
            if q[i:i+2] in ('->', '||', '!=', '<>', '>=', '<=', ':=', '+=', '-='):
                op = q[i:i+2]
                tokens.append(('OPERATOR', op, i, i+2))
                i += 2
                continue
            if q[i] in ('=', '<', '>', '+', '-', '*', '/', '%', '&', '|', '^', '~'):
                tokens.append(('OPERATOR', q[i], i, i+1))
                i += 1
                continue

            # Check Whitespace
            if q[i].isspace():
                start = i
                while i < n and q[i].isspace():
                    i += 1
                tokens.append(('WHITESPACE', q[start:i], start, i))
                continue

            # Check Words
            if q[i].isalpha() or q[i] == '_':
                start = i
                while i < n and (q[i].isalnum() or q[i] == '_'):
                    i += 1
                tokens.append(('WORD', q[start:i], start, i))
                continue

            # Check Numbers
            if q[i].isdigit():
                start = i
                while i < n and (q[i].isdigit() or q[i] == '.' or q[i].lower() in ('x', 'a', 'b', 'c', 'd', 'e', 'f')):
                    i += 1
                tokens.append(('NUMBER', q[start:i], start, i))
                continue

            # Other Punctuation
            tokens.append(('PUNCTUATION', q[i], i, i+1))
            i += 1

        return tokens

    tokens = tokenize_sql(query)

    # 1. Check for Obfuscation / inline comment evasion & comment boundary injection
    for i in range(len(tokens)):
        tok_type, tok_val, start, end = tokens[i]
        if tok_type == 'COMMENT_C':
            # Check if comment is immediately adjacent to a quote
            if start > 0 and query[start - 1] in ("'", '"'):
                return False, f"Comment-boundary injection signature detected: {query[start-1]}{tok_val}"
            # Check MySQL executable comment evasion
            if tok_val.startswith('/*!'):
                return False, f"MySQL executable comment evasion detected: {tok_val}"

            # Check if it splits a word/number directly (e.g. UN/**/ION)
            has_before = False
            if i > 0:
                prev_type, prev_val, _, prev_end = tokens[i-1]
                if prev_type in ('WORD', 'NUMBER') and prev_end == start:
                    has_before = True
            has_after = False
            if i + 1 < len(tokens):
                next_type, next_val, next_start, _ = tokens[i+1]
                if next_type in ('WORD', 'NUMBER') and next_start == end:
                    has_after = True
            if has_before and has_after:
                return False, f"Inline comment evasion detected: {tokens[i-1][1]}{tok_val}{tokens[i+1][1]}"

        elif tok_type == 'COMMENT_LINE':
            # Check if comment starts immediately after a quote (e.g. admin'--)
            if start > 0 and query[start - 1] in ("'", '"'):
                return False, f"Comment-boundary injection signature detected: {query[start-1]}{tok_val}"
            # Extract content of comment after -- or # and check for enclosed quote
            prefix_len = 2 if tok_val.startswith('--') else 1
            comment_content = tok_val[prefix_len:].lstrip()
            if comment_content and comment_content[0] in ("'", '"'):
                return False, f"Comment-boundary injection signature detected: {tok_val}"

    # Filter tokens: ignore comments, whitespaces, and strip parentheses for tautology detection
    filtered_tokens = []
    tautology_tokens = []

    for tok in tokens:
        tok_type, tok_val, _, _ = tok
        if tok_type in ('COMMENT_C', 'COMMENT_LINE', 'WHITESPACE'):
            continue
        filtered_tokens.append((tok_type, tok_val))
        if tok_val not in ('(', ')'):
            tautology_tokens.append((tok_type, tok_val))

    # 2. Check for Stacked query execution
    n_filt = len(filtered_tokens)
    for i in range(n_filt):
        tok_type, tok_val = filtered_tokens[i]
        if tok_type == 'PUNCTUATION' and tok_val == ';':
            for j in range(i + 1, n_filt):
                next_type, next_val = filtered_tokens[j]
                if next_type == 'WORD':
                    next_val_lower = next_val.lower()
                    if next_val_lower in (
                        'select', 'insert', 'update', 'delete', 'drop', 'exec', 
                        'execute', 'truncate', 'alter', 'create', 'rename', 
                        'replace', 'merge', 'grant', 'revoke', 'declare', 'call',
                        'xp_cmdshell'
                    ):
                        return False, f"Stacked query execution signature detected: ; {next_val}"

    # 3. Check for UNION-based data exfiltration
    for i in range(n_filt):
        tok_type, tok_val = filtered_tokens[i]
        if tok_type == 'WORD' and tok_val.lower() == 'union':
            for j in range(i + 1, n_filt):
                next_type, next_val = filtered_tokens[j]
                if next_type == 'WORD' and next_val.lower() == 'select':
                    return False, "UNION-based data exfiltration signature detected"

    # 4. Check for Time-based blind execution
    for i in range(n_filt):
        tok_type, tok_val = filtered_tokens[i]
        if tok_type == 'WORD':
            val_lower = tok_val.lower()
            if val_lower in ('pg_sleep', 'sleep', 'benchmark'):
                if i + 1 < n_filt and filtered_tokens[i+1] == ('PUNCTUATION', '('):
                    return False, f"Time-based blind execution signature detected: {tok_val}("
            elif val_lower == 'waitfor':
                if i + 1 < n_filt and filtered_tokens[i+1][0] == 'WORD' and filtered_tokens[i+1][1].lower() == 'delay':
                    return False, "Time-based blind execution signature detected: WAITFOR DELAY"

    # 5. Check for Boolean/Tautology injection
    n_taut = len(tautology_tokens)
    for i in range(n_taut):
        tok_type, tok_val = tautology_tokens[i]
        if (tok_type == 'WORD' and tok_val.lower() in ('or', 'and')) or (tok_type == 'OPERATOR' and tok_val == '||'):
            # Check for immediate truthy literal
            if i + 1 < n_taut:
                next_type, next_val = tautology_tokens[i+1]
                next_val_lower = next_val.lower()
                if next_type == 'NUMBER' and next_val != '0':
                    return False, f"Boolean/Tautology injection signature detected: {tok_val} {next_val}"
                if next_type == 'WORD' and next_val_lower == 'true':
                    return False, f"Boolean/Tautology injection signature detected: {tok_val} {next_val}"

            # Check LHS = RHS, LHS LIKE RHS, or LHS <> RHS
            if i + 3 < n_taut:
                lhs_type, lhs_val = tautology_tokens[i+1]
                op_type, op_val = tautology_tokens[i+2]
                rhs_type, rhs_val = tautology_tokens[i+3]
                op_val_lower = op_val.lower()

                valid_types = ('NUMBER', 'STRING_SINGLE', 'STRING_DOUBLE', 'WORD')
                if lhs_type in valid_types and rhs_type in valid_types:
                    lhs_norm = lhs_val.lower()
                    rhs_norm = rhs_val.lower()

                    if op_val == '=' or op_val_lower == 'like':
                        if lhs_norm == rhs_norm:
                            return False, f"Boolean/Tautology injection signature detected: {tok_val} {lhs_val} {op_val} {rhs_val}"
                    elif op_val in ('<>', '!='):
                        if lhs_norm != rhs_norm:
                            return False, f"Boolean/Tautology injection signature detected: {tok_val} {lhs_val} {op_val} {rhs_val}"

    return True, "SAFE"
