import ast

class Scope:
    def __init__(self, parent=None, node=None):
        self.parent = parent
        self.node = node
        self.potential_locals = set()
        self.locals = set()
        self.globals = set()
        self.nonlocals = set()
        self.references = []
        self.children = []

    def finalize(self):
        self.locals = self.potential_locals - self.globals - self.nonlocals
        for child in self.children:
            child.finalize()

class ScopeAnalyzer(ast.NodeVisitor):
    def __init__(self):
        self.current_scope = Scope(node=None)
        self.scopes = [self.current_scope]

    def visit_Module(self, node):
        self.current_scope.node = node
        self.generic_visit(node)

    def visit_FunctionDef(self, node):
        self.current_scope.potential_locals.add(node.name)
        new_scope = Scope(parent=self.current_scope, node=node)
        self.current_scope.children.append(new_scope)
        self.scopes.append(new_scope)

        prev_scope = self.current_scope
        for decorator in node.decorator_list:
            self.visit(decorator)
        for default in node.args.defaults + node.args.kw_defaults:
            if default is not None:
                self.visit(default)

        self.current_scope = new_scope
        for arg in node.args.posonlyargs + node.args.args + node.args.kwonlyargs:
            self.current_scope.potential_locals.add(arg.arg)
            if arg.annotation:
                self.current_scope = prev_scope
                self.visit(arg.annotation)
                self.current_scope = new_scope

        if node.args.vararg:
            self.current_scope.potential_locals.add(node.args.vararg.arg)
            if node.args.vararg.annotation:
                self.current_scope = prev_scope
                self.visit(node.args.vararg.annotation)
                self.current_scope = new_scope
        if node.args.kwarg:
            self.current_scope.potential_locals.add(node.args.kwarg.arg)
            if node.args.kwarg.annotation:
                self.current_scope = prev_scope
                self.visit(node.args.kwarg.annotation)
                self.current_scope = new_scope

        if node.returns:
            self.current_scope = prev_scope
            self.visit(node.returns)
            self.current_scope = new_scope

        for stmt in node.body:
            self.visit(stmt)

        self.current_scope = prev_scope

    def visit_AsyncFunctionDef(self, node):
        self.visit_FunctionDef(node)

    def visit_ClassDef(self, node):
        self.current_scope.potential_locals.add(node.name)
        new_scope = Scope(parent=self.current_scope, node=node)
        self.current_scope.children.append(new_scope)
        self.scopes.append(new_scope)

        prev_scope = self.current_scope
        for decorator in node.decorator_list:
            self.visit(decorator)
        for base in node.bases:
            self.visit(base)
        for kw in node.keywords:
            self.visit(kw)

        self.current_scope = new_scope
        for stmt in node.body:
            self.visit(stmt)

        self.current_scope = prev_scope

    def visit_Name(self, node):
        if isinstance(node.ctx, ast.Load):
            self.current_scope.references.append((node.id, self.current_scope, node))
        elif isinstance(node.ctx, (ast.Store, ast.Del)):
            self.current_scope.potential_locals.add(node.id)
        self.generic_visit(node)

    def visit_Global(self, node):
        for name in node.names:
            self.current_scope.globals.add(name)

    def visit_Nonlocal(self, node):
        for name in node.names:
            self.current_scope.nonlocals.add(name)

    def visit_Import(self, node):
        for alias in node.names:
            name = alias.asname or alias.name.split('.')[0]
            self.current_scope.potential_locals.add(name)

    def visit_ImportFrom(self, node):
        for alias in node.names:
            name = alias.asname or alias.name
            self.current_scope.potential_locals.add(name)

    def visit_comprehension_node(self, node, visit_contents_fn):
        new_scope = Scope(parent=self.current_scope, node=node)
        self.current_scope.children.append(new_scope)
        self.scopes.append(new_scope)

        prev_scope = self.current_scope
        self.current_scope = new_scope
        for gen in node.generators:
            self.visit(gen.target)
            self.current_scope = prev_scope
            self.visit(gen.iter)
            self.current_scope = new_scope
            for ifs in gen.ifs:
                self.visit(ifs)
        visit_contents_fn()
        self.current_scope = prev_scope

    def visit_ListComp(self, node):
        self.visit_comprehension_node(node, lambda: self.visit(node.elt))

    def visit_SetComp(self, node):
        self.visit_comprehension_node(node, lambda: self.visit(node.elt))

    def visit_GeneratorExp(self, node):
        self.visit_comprehension_node(node, lambda: self.visit(node.elt))

    def visit_DictComp(self, node):
        self.visit_comprehension_node(node, lambda: (self.visit(node.key), self.visit(node.value)))

def resolve_name(name, scope):
    curr = scope
    in_function = False
    while curr is not None:
        if isinstance(curr.node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.Lambda)):
            in_function = True
        if isinstance(curr.node, ast.ClassDef) and in_function:
            curr = curr.parent
            continue
        if name in curr.locals:
            return curr
        curr = curr.parent
    return None

def find_scope_of_node(target_node, scopes, parent_map):
    curr = target_node
    scope_by_node = {s.node: s for s in scopes}
    while curr is not None:
        if curr in scope_by_node:
            return scope_by_node[curr]
        curr = parent_map.get(curr)
    return None

class PruningTransformer(ast.NodeTransformer):
    def __init__(self, unused_imports, dead_functions):
        self.unused_imports = unused_imports
        self.dead_functions = dead_functions

    def visit_Import(self, node):
        new_names = [alias for alias in node.names if (node, alias) not in self.unused_imports]
        if not new_names:
            return None
        node.names = new_names
        return node

    def visit_ImportFrom(self, node):
        new_names = [alias for alias in node.names if (node, alias) not in self.unused_imports]
        if not new_names:
            return None
        node.names = new_names
        return node

    def visit_FunctionDef(self, node):
        if node in self.dead_functions:
            return None
        self.generic_visit(node)
        return node

    def visit_AsyncFunctionDef(self, node):
        if node in self.dead_functions:
            return None
        self.generic_visit(node)
        return node

def prune_dead_code_and_imports(source_code: str) -> str:
    try:
        tree = ast.parse(source_code)
    except SyntaxError:
        return source_code

    # 1. Build parent map
    parent_map = {}
    for node in ast.walk(tree):
        for child in ast.iter_child_nodes(node):
            parent_map[child] = node

    # 2. Scope analysis
    analyzer = ScopeAnalyzer()
    analyzer.visit(tree)
    analyzer.scopes[0].finalize()

    # 3. Candidate top-level private functions
    private_funcs = {}
    for child in tree.body:
        if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)) and child.name.startswith('_'):
            private_funcs[child.name] = child

    # 4. Candidate imports
    candidate_imports = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name != '*':
                    bound = alias.asname or alias.name.split('.')[0]
                    candidate_imports.append((node, alias, bound))
        elif isinstance(node, ast.ImportFrom):
            for alias in node.names:
                if alias.name != '*':
                    bound = alias.asname or alias.name
                    candidate_imports.append((node, alias, bound))

    # 5. Iterative reachability for scopes and globals
    reachable_scopes = {analyzer.scopes[0]}
    reachable_globals = set()

    while True:
        changed = False

        # Any global name referenced in any reachable scope is reachable
        for s in analyzer.scopes:
            if s in reachable_scopes:
                for ref_name, ref_scope, ref_node in s.references:
                    res = resolve_name(ref_name, ref_scope)
                    if res is not None and res.parent is None:
                        if ref_name not in reachable_globals:
                            # Exclude self-recursion
                            if ref_name in private_funcs and s.node is private_funcs[ref_name]:
                                continue
                            reachable_globals.add(ref_name)
                            changed = True

        # Any scope is reachable if its parent is reachable, AND:
        # - it is not a top-level private function, OR
        # - it is a top-level private function whose name is in reachable_globals
        for s in analyzer.scopes:
            if s not in reachable_scopes:
                if s.parent in reachable_scopes:
                    is_top_level_private = (
                        isinstance(s.node, (ast.FunctionDef, ast.AsyncFunctionDef))
                        and s.parent.parent is None
                        and s.node.name.startswith('_')
                    )
                    if not is_top_level_private or s.node.name in reachable_globals:
                        reachable_scopes.add(s)
                        changed = True

        if not changed:
            break

    # 6. Check which candidate imports are used
    import_used = {}
    for node, alias, bound in candidate_imports:
        import_scope = find_scope_of_node(node, analyzer.scopes, parent_map)

        # Check if there is any reference in a reachable scope that resolves to import_scope
        used = False
        if import_scope in reachable_scopes:
            for s in analyzer.scopes:
                if s in reachable_scopes:
                    for ref_name, ref_scope, ref_node in s.references:
                        if ref_name == bound:
                            res = resolve_name(ref_name, ref_scope)
                            if res is import_scope:
                                used = True
                                break
                    if used:
                        break
        import_used[(node, alias)] = used

    # 7. Identify dead nodes
    unused_imports = {key for key, used in import_used.items() if not used}

    dead_functions = set()
    for name, func_node in private_funcs.items():
        if name not in reachable_globals:
            dead_functions.add(func_node)

    # 8. Apply transformation
    transformer = PruningTransformer(unused_imports, dead_functions)
    new_tree = transformer.visit(tree)
    return ast.unparse(new_tree)
