import time
import threading
from collections import OrderedDict
from typing import Any, Optional

class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl = default_ttl_seconds
        self.cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self.lock = threading.RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self.lock:
            ttl_to_use = ttl if ttl is not None else self.default_ttl
            expire_time = time.time() + ttl_to_use

            if key in self.cache:
                # Update existing key and move to the end (most recently used)
                self.cache[key] = (value, expire_time)
                self.cache.move_to_end(key)
            else:
                # Evict if at capacity
                if len(self.cache) >= self.capacity:
                    self.cleanup_expired()
                    # If still at capacity after cleanup, evict LRU (first item)
                    if len(self.cache) >= self.capacity:
                        self.cache.popitem(last=False)

                self.cache[key] = (value, expire_time)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key not in self.cache:
                return None

            value, expire_time = self.cache[key]
            if time.time() > expire_time:
                del self.cache[key]
                return None

            # Item is accessed, mark as most recently used
            self.cache.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self.lock:
            now = time.time()
            expired_keys = [k for k, v in self.cache.items() if now > v[1]]
            for k in expired_keys:
                del self.cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self.lock:
            now = time.time()
            # Returns the count of valid (non-expired) items without explicitly removing them
            return sum(1 for v in self.cache.values() if now <= v[1])
