class CircularDependencyError(Exception):
    pass

class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        tasks = set(dependencies.keys())
        for deps in dependencies.values():
            tasks.update(deps)

        in_degree = {task: 0 for task in tasks}
        out_edges = {task: [] for task in tasks}

        for task, deps in dependencies.items():
            unique_deps = set(deps)
            in_degree[task] += len(unique_deps)
            for dep in unique_deps:
                out_edges[dep].append(task)

        result = []
        current_stage = sorted([task for task, degree in in_degree.items() if degree == 0])

        resolved_count = 0
        while current_stage:
            result.append(current_stage)
            resolved_count += len(current_stage)

            next_stage = []
            for task in current_stage:
                for dependent_task in out_edges[task]:
                    in_degree[dependent_task] -= 1
                    if in_degree[dependent_task] == 0:
                        next_stage.append(dependent_task)
            current_stage = sorted(next_stage)

        if resolved_count < len(tasks):
            raise CircularDependencyError("Circular dependency detected.")

        return result
