import time
import threading
from collections import deque
from typing import Optional

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.requests: dict[str, deque[float]] = {}
        self.lock = threading.Lock()

    def _cleanup(self, key: str, current_time: float) -> None:
        """Removes expired timestamps from the sliding window for a given key."""
        if key not in self.requests:
            return

        window_start = current_time - self.window_seconds
        dq = self.requests[key]

        # Remove timestamps that are older than the window start
        while dq and dq[0] <= window_start:
            dq.popleft()

        # Clean up empty deques to prevent memory leaks
        if not dq:
            del self.requests[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            if self.max_requests <= 0:
                return False, float('inf')

            self._cleanup(key, timestamp)

            dq = self.requests.get(key)
            if dq is None:
                dq = deque()
                self.requests[key] = dq

            if len(dq) < self.max_requests:
                dq.append(timestamp)
                return True, 0.0
            else:
                # Calculate time until the oldest request in the window expires
                retry_after = (dq[0] + self.window_seconds) - timestamp
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            if self.max_requests <= 0:
                return 0

            self._cleanup(key, timestamp)

            dq = self.requests.get(key)
            if dq is None:
                return self.max_requests

            return max(0, self.max_requests - len(dq))

