import asyncio
import dataclasses
import itertools
from typing import Callable, Any, Optional, Tuple

@dataclasses.dataclass(order=True)
class _PrioritizedItem:
    priority: int
    count: int
    future: asyncio.Future = dataclasses.field(compare=False)
    coro_func: Callable = dataclasses.field(compare=False)
    args: Tuple = dataclasses.field(compare=False)
    kwargs: dict = dataclasses.field(compare=False)

class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self.concurrency = concurrency
        self.queue: asyncio.PriorityQueue[_PrioritizedItem] = asyncio.PriorityQueue(maxsize=max_queue_size)
        self.workers: list[asyncio.Task] = []
        self._shutting_down = False
        self._counter = itertools.count()

    async def submit(self, coro_func: Callable, *args: Any, priority: int = 0, **kwargs: Any) -> asyncio.Future:
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()

        # PriorityQueue retrieves lowest first; invert priority for higher-first execution
        item = _PrioritizedItem(
            priority=-priority,
            count=next(self._counter),  # Stable sort for equal priorities
            future=future,
            coro_func=coro_func,
            args=args,
            kwargs=kwargs
        )
        await self.queue.put(item)
        return future

    async def _worker(self) -> None:
        while True:
            try:
                item = await self.queue.get()
                try:
                    if not item.future.cancelled():
                        result = await item.coro_func(*item.args, **item.kwargs)
                        if not item.future.done():
                            item.future.set_result(result)
                except asyncio.CancelledError:
                    if not item.future.done():
                        item.future.cancel()
                    raise
                except Exception as e:
                    if not item.future.done():
                        item.future.set_exception(e)
                finally:
                    self.queue.task_done()
            except asyncio.CancelledError:
                break

    async def start(self) -> None:
        if self.workers:
            return
        self._shutting_down = False
        for _ in range(self.concurrency):
            task = asyncio.create_task(self._worker())
            self.workers.append(task)

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        self._shutting_down = True

        if not self.workers:
            return

        if not drain:
            # Empty the queue and cancel all pending futures
            while not self.queue.empty():
                try:
                    item = self.queue.get_nowait()
                    if not item.future.done():
                        item.future.cancel()
                    self.queue.task_done()
                except asyncio.QueueEmpty:
                    break

        async def _drain_and_cancel() -> None:
            if drain:
                await self.queue.join()

            for worker in self.workers:
                worker.cancel()

            if self.workers:
                await asyncio.gather(*self.workers, return_exceptions=True)

        try:
            if timeout is not None:
                await asyncio.wait_for(_drain_and_cancel(), timeout=timeout)
            else:
                await _drain_and_cancel()
        except asyncio.TimeoutError:
            # If draining times out, force cancel all workers
            for worker in self.workers:
                worker.cancel()
            if self.workers:
                await asyncio.gather(*self.workers, return_exceptions=True)
        finally:
            self.workers.clear()
