from typing import Any, List

class QuorumCluster:
    def __init__(self, node_ids: List[str]):
        self.node_ids = node_ids
        self.N = len(node_ids)
        self.quorum = (self.N // 2) + 1

        # Track the current active network partitions as sets of node IDs
        self.partitions = [set(node_ids)]

        # State mapping: node_id -> {key: (version, value)}
        # Using a logical clock (version) per key to track the most recent committed write
        self.node_states = {node: {} for node in node_ids}

    def partition(self, group_a: List[str], group_b: List[str]) -> None:
        """Divides cluster into isolated network partitions."""
        self.partitions = [set(group_a), set(group_b)]

    def heal_partition(self) -> None:
        """Restores full connectivity and synchronizes state across all nodes."""
        self.partitions = [set(self.node_ids)]

        # Determine the most up-to-date value for each key across all nodes globally
        latest_state = {}
        for node in self.node_ids:
            for key, (version, value) in self.node_states[node].items():
                if key not in latest_state or version > latest_state[key][0]:
                    latest_state[key] = (version, value)

        # Synchronize every node's local state to match the healed global state
        for node in self.node_ids:
            self.node_states[node] = {k: (v, val) for k, (v, val) in latest_state.items()}

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write. Commits only if the node's partition has a strict majority.
        """
        active_partition = None
        for p in self.partitions:
            if from_node in p:
                active_partition = p
                break

        # Reject the write if the node's partition is a minority (split-brain prevention)
        if active_partition is None or len(active_partition) < self.quorum:
            return False

        # Determine the next logical version for this key within the quorum partition
        max_version = 0
        for node in active_partition:
            if key in self.node_states[node]:
                max_version = max(max_version, self.node_states[node][key][0])

        new_version = max_version + 1

        # Apply the committed write to all nodes present in this majority partition
        for node in active_partition:
            self.node_states[node][key] = (new_version, value)

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """Returns the committed value for the key on the specified node, or None."""
        if from_node in self.node_states and key in self.node_states[from_node]:
            return self.node_states[from_node][key][1]
        return None
