class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        all_tasks = set(dependencies)
        for required_tasks in dependencies.values():
            all_tasks.update(required_tasks)

        remaining = {
            task: set(dependencies.get(task, []))
            for task in all_tasks
        }
        stages: list[list[str]] = []

        while remaining:
            ready = sorted(
                task for task, required_tasks in remaining.items()
                if not required_tasks
            )

            if not ready:
                raise CircularDependencyError("Circular dependency detected")

            stages.append(ready)

            for task in ready:
                del remaining[task]

            completed = set(ready)
            for required_tasks in remaining.values():
                required_tasks.difference_update(completed)

        return stages
