from collections import deque
from math import isfinite
from threading import RLock
from time import monotonic
from typing import Optional


class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        if isinstance(max_requests, bool) or not isinstance(max_requests, int) or max_requests <= 0:
            raise ValueError("max_requests must be a positive integer")

        self._window_seconds = float(window_seconds)
        if not isfinite(self._window_seconds) or self._window_seconds <= 0:
            raise ValueError("window_seconds must be a positive finite number")

        self._max_requests = max_requests
        self._requests: dict[str, deque[float]] = {}
        self._lock = RLock()

    def allow_request(
        self, key: str, timestamp: Optional[float] = None
    ) -> tuple[bool, float]:
        now = self._resolve_timestamp(timestamp)

        with self._lock:
            requests = self._requests.setdefault(key, deque())
            self._prune(requests, now)

            if len(requests) < self._max_requests:
                requests.append(now)
                return True, 0.0

            retry_after = max(0.0, requests[0] + self._window_seconds - now)
            return False, retry_after

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = self._resolve_timestamp(timestamp)

        with self._lock:
            requests = self._requests.get(key)
            if requests is None:
                return self._max_requests

            self._prune(requests, now)

            if not requests:
                self._requests.pop(key, None)
                return self._max_requests

            return self._max_requests - len(requests)

    def _prune(self, requests: deque[float], now: float) -> None:
        cutoff = now - self._window_seconds
        while requests and requests[0] <= cutoff:
            requests.popleft()

    @staticmethod
    def _resolve_timestamp(timestamp: Optional[float]) -> float:
        now = monotonic() if timestamp is None else float(timestamp)
        if not isfinite(now):
            raise ValueError("timestamp must be a finite number")
        return now
