import asyncio
import itertools
from typing import Any, Callable, Optional


class AsyncWorkerPool:
    _STOP = object()

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be non-negative")

        self._concurrency = concurrency
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(
            maxsize=max_queue_size
        )
        self._sequence = itertools.count()
        self._workers: set[asyncio.Task] = set()
        self._executing: dict[asyncio.Future, asyncio.Future] = {}
        self._pending_puts: set[asyncio.Task] = set()
        self._lifecycle_lock = asyncio.Lock()
        self._started = False
        self._shutdown = False

    async def start(self) -> None:
        async with self._lifecycle_lock:
            if self._shutdown:
                raise RuntimeError("Pool is shutting down")

            if self._started:
                return

            self._started = True
            for _ in range(self._concurrency):
                worker = asyncio.create_task(self._worker())
                self._workers.add(worker)
                worker.add_done_callback(self._workers.discard)

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        if not isinstance(priority, int):
            raise TypeError("priority must be an integer")
        if self._shutdown:
            raise RuntimeError("Pool is shutting down")

        await self.start()

        if self._shutdown:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        result_future = loop.create_future()
        item = (-priority, next(self._sequence), (result_future, coro_func, args, kwargs))

        put_task = asyncio.create_task(self._queue.put(item))
        self._pending_puts.add(put_task)

        try:
            await put_task
        except asyncio.CancelledError:
            result_future.cancel()
            if self._shutdown:
                raise RuntimeError("Pool is shutting down") from None
            raise
        finally:
            self._pending_puts.discard(put_task)

        if self._shutdown:
            result_future.cancel()
            raise RuntimeError("Pool is shutting down")

        return result_future

    async def shutdown(
        self,
        drain: bool = True,
        timeout: Optional[float] = 5.0,
    ) -> None:
        if timeout is not None and timeout < 0:
            raise ValueError("timeout must be non-negative or None")

        async with self._lifecycle_lock:
            if self._shutdown:
                return

            self._shutdown = True
            deadline = (
                None
                if timeout is None
                else asyncio.get_running_loop().time() + timeout
            )

            self._cancel_pending_submissions()

            try:
                if drain:
                    await self._await_until(self._queue.join(), deadline)

                    for _ in list(self._workers):
                        await self._await_until(
                            self._queue.put(
                                (0, next(self._sequence), self._STOP)
                            ),
                            deadline,
                        )
                else:
                    self._force_stop()

                workers = list(self._workers)
                if workers:
                    await self._await_until(
                        asyncio.gather(*workers, return_exceptions=True),
                        deadline,
                    )
            except TimeoutError:
                self._force_stop()
                await asyncio.sleep(0)
            except asyncio.CancelledError:
                self._force_stop()
                raise

    async def _worker(self) -> None:
        while True:
            _, _, item = await self._queue.get()

            try:
                if item is self._STOP:
                    return

                result_future, coro_func, args, kwargs = item

                if result_future.cancelled():
                    continue

                try:
                    awaitable = coro_func(*args, **kwargs)
                    running_task = asyncio.ensure_future(awaitable)
                    self._executing[running_task] = result_future

                    try:
                        result = await running_task
                    except asyncio.CancelledError:
                        if not result_future.done():
                            result_future.cancel()

                        current = asyncio.current_task()
                        if current is not None and current.cancelling():
                            raise
                    except BaseException as exc:
                        if not result_future.done():
                            result_future.set_exception(exc)
                    else:
                        if not result_future.done():
                            result_future.set_result(result)
                    finally:
                        self._executing.pop(running_task, None)

                except BaseException as exc:
                    if not result_future.done():
                        result_future.set_exception(exc)

            finally:
                self._queue.task_done()

    async def _await_until(self, awaitable: Any, deadline: Optional[float]) -> Any:
        if deadline is None:
            return await awaitable

        remaining = deadline - asyncio.get_running_loop().time()
        if remaining <= 0:
            raise TimeoutError

        return await asyncio.wait_for(awaitable, timeout=remaining)

    def _cancel_pending_submissions(self) -> None:
        for put_task in list(self._pending_puts):
            put_task.cancel()

    def _force_stop(self) -> None:
        self._cancel_pending_submissions()

        while True:
            try:
                _, _, item = self._queue.get_nowait()
            except asyncio.QueueEmpty:
                break

            try:
                if item is not self._STOP:
                    result_future, _, _, _ = item
                    if not result_future.done():
                        result_future.cancel()
            finally:
                self._queue.task_done()

        for running_task, result_future in list(self._executing.items()):
            if not result_future.done():
                result_future.cancel()
            running_task.cancel()

        for worker in list(self._workers):
            worker.cancel()
