class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if not node_ids or len(set(node_ids)) != len(node_ids):
            raise ValueError("node_ids must be non-empty and unique")

        self.node_ids = list(node_ids)
        self.node_count = len(node_ids)
        self.quorum_threshold = self.node_count // 2 + 1
        self._states = {node_id: {} for node_id in self.node_ids}
        self._committed_state = {}
        self._partitions = None

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        all_nodes = group_a + group_b

        if (
            len(all_nodes) != len(self.node_ids)
            or len(set(all_nodes)) != len(all_nodes)
            or set(all_nodes) != set(self.node_ids)
        ):
            raise ValueError("Partitions must be disjoint and include every cluster node")

        self._partitions = (set(group_a), set(group_b))

    def heal_partition(self) -> None:
        for node_id in self.node_ids:
            self._states[node_id] = dict(self._committed_state)

        self._partitions = None

    def propose_write(self, from_node: str, key: str, value: object) -> bool:
        if from_node not in self._states:
            raise ValueError(f"Unknown node: {from_node}")

        if self._partitions is None:
            reachable_nodes = set(self.node_ids)
        else:
            group_a, group_b = self._partitions
            reachable_nodes = group_a if from_node in group_a else group_b

        if len(reachable_nodes) < self.quorum_threshold:
            return False

        self._committed_state[key] = value
        for node_id in reachable_nodes:
            self._states[node_id][key] = value

        return True

    def read_value(self, from_node: str, key: str) -> object | None:
        if from_node not in self._states:
            raise ValueError(f"Unknown node: {from_node}")

        return self._states[from_node].get(key)
