import struct
import zlib


class BinaryFrameParser:
    MAGIC = b"SX"
    HEADER_SIZE = 8
    CHECKSUM_SIZE = 4

    def __init__(self) -> None:
        self._buffer = bytearray()

    def feed(self, data: bytes) -> list[tuple[int, bytes]]:
        self._buffer.extend(data)
        packets: list[tuple[int, bytes]] = []

        while True:
            magic_index = self._buffer.find(self.MAGIC)

            if magic_index == -1:
                if self._buffer.endswith(b"S"):
                    self._buffer[:] = b"S"
                else:
                    self._buffer.clear()
                break

            if magic_index > 0:
                del self._buffer[:magic_index]

            if len(self._buffer) < self.HEADER_SIZE + self.CHECKSUM_SIZE:
                break

            msg_type = struct.unpack(">H", self._buffer[2:4])[0]
            payload_length = struct.unpack(">I", self._buffer[4:8])[0]
            frame_size = self.HEADER_SIZE + payload_length + self.CHECKSUM_SIZE

            if len(self._buffer) < frame_size:
                break

            payload_end = self.HEADER_SIZE + payload_length
            payload = bytes(self._buffer[self.HEADER_SIZE:payload_end])
            received_crc = struct.unpack(
                ">I", self._buffer[payload_end:frame_size]
            )[0]
            expected_crc = zlib.crc32(self._buffer[2:payload_end]) & 0xFFFFFFFF

            if received_crc == expected_crc:
                packets.append((msg_type, payload))
                del self._buffer[:frame_size]
            else:
                del self._buffer[:len(self.MAGIC)]

        return packets
