def verify_jwt(
    token: str,
    secret_key: str,
    allowed_algs: list[str] | None = None,
) -> dict:
    if allowed_algs is None:
        allowed_algs = ["HS256"]

    def base64url_decode(value: str) -> bytes:
        padding = "=" * (-len(value) % 4)
        try:
            return base64.urlsafe_b64decode(value + padding)
        except Exception as exc:
            raise ValueError("Invalid Base64 URL encoding") from exc

    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    try:
        header = json.loads(base64url_decode(parts[0]))
        payload = json.loads(base64url_decode(parts[1]))
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ValueError("Invalid JWT JSON") from exc

    if not isinstance(header, dict) or not isinstance(payload, dict):
        raise ValueError("Invalid JWT content")

    alg = header.get("alg")
    if alg not in allowed_algs or alg != "HS256":
        raise ValueError("Unapproved JWT algorithm")

    now = time.time()
    if "exp" in payload:
        try:
            if float(payload["exp"]) <= now:
                raise ValueError("Token expired")
        except (TypeError, ValueError) as exc:
            if isinstance(exc, ValueError) and str(exc) == "Token expired":
                raise
            raise ValueError("Invalid expiration claim") from exc

    signature = base64url_decode(parts[2])
    signing_input = f"{parts[0]}.{parts[1]}".encode("ascii")
    expected_sig = hmac.new(
        secret_key.encode("utf-8"),
        signing_input,
        hashlib.sha256,
    ).digest()

    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    return payload
