def parse_markdown_links(text: str) -> list[dict[str, str]]:
    """Extract valid [title](http(s)://url) links in linear time."""
    results: list[dict[str, str]] = []
    title_chars = set(
        "abcdefghijklmnopqrstuvwxyz"
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        "0123456789 _"
    )

    i = 0
    n = len(text)

    while i < n:
        if text[i] != "[":
            i += 1
            continue

        # Read a title containing only permitted characters.
        title_start = i + 1
        j = title_start
        while j < n and text[j] in title_chars:
            j += 1

        if j >= n or text[j] != "]" or j + 1 >= n or text[j + 1] != "(":
            # Continue at the first character that invalidated this candidate.
            i = max(i + 1, j)
            continue

        url_start = j + 2
        if text.startswith("https://", url_start):
            url_pos = url_start + len("https://")
        elif text.startswith("http://", url_start):
            url_pos = url_start + len("http://")
        else:
            i = j + 1
            continue

        # URLs cannot contain whitespace or a closing parenthesis.
        while url_pos < n and not text[url_pos].isspace() and text[url_pos] != ")":
            url_pos += 1

        if url_pos < n and text[url_pos] == ")" and url_pos > url_start:
            results.append({
                "title": text[title_start:j],
                "url": text[url_start:url_pos],
            })
            i = url_pos + 1
        else:
            i = max(i + 1, url_pos)

    return results
