def is_safe_sql_query(query: str) -> tuple[bool, str]:
    import re

    if not isinstance(query, str) or not query.strip():
        return False, "INVALID_QUERY"

    source = query
    output: list[str] = []
    string_values: dict[str, str] = {}
    inline_evasion = False
    unterminated_string = False
    mysql_version_comment = False
    i = 0
    placeholder_index = 0
    length = len(source)

    def previous_word() -> str:
        match = re.search(r"[A-Za-z_]+$", "".join(output))
        return match.group(0).lower() if match else ""

    def next_word(position: int) -> str:
        match = re.match(r"[A-Za-z_]+", source[position:])
        return match.group(0).lower() if match else ""

    while i < length:
        char = source[i]
        next_char = source[i + 1] if i + 1 < length else ""

        # SQL line comments
        if (char == "-" and next_char == "-") or char == "#":
            if char == "-" and next_char == "-":
                i += 2
            else:
                i += 1
            while i < length and source[i] not in "\r\n":
                i += 1
            output.append(" ")
            continue

        # SQL block comments, including MySQL executable comments.
        if char == "/" and next_char == "*":
            if i + 2 < length and source[i + 2] == "!":
                mysql_version_comment = True

            before = previous_word()
            end = source.find("*/", i + 2)
            if end == -1:
                return False, "COMMENT_EVASION"

            after = next_word(end + 2)
            combined = before + after
            if combined in {"union", "select", "or", "drop", "delete", "exec", "execute"}:
                inline_evasion = True

            i = end + 2
            continue

        # Single-quoted values are excluded from signature inspection.
        if char == "'":
            i += 1
            value: list[str] = []
            closed = False

            while i < length:
                if source[i] == "'" and i + 1 < length and source[i + 1] == "'":
                    value.append("'")
                    i += 2
                elif source[i] == "\\" and i + 1 < length:
                    value.append(source[i + 1])
                    i += 2
                elif source[i] == "'":
                    i += 1
                    closed = True
                    break
                else:
                    value.append(source[i])
                    i += 1

            if not closed:
                unterminated_string = True
                break

            placeholder = f"__str_{placeholder_index}__"
            placeholder_index += 1
            string_values[placeholder] = "".join(value)
            output.append(f" {placeholder} ")
            continue

        # Double quotes and backticks are identifiers, not executable SQL keywords.
        if char in {'"', "`"}:
            quote = char
            i += 1
            closed = False

            while i < length:
                if source[i] == quote and i + 1 < length and source[i + 1] == quote:
                    i += 2
                elif source[i] == quote:
                    i += 1
                    closed = True
                    break
                else:
                    i += 1

            if not closed:
                return False, "INVALID_QUERY"

            output.append(" __identifier__ ")
            continue

        output.append(char)
        i += 1

    if mysql_version_comment or inline_evasion:
        return False, "COMMENT_EVASION"

    if unterminated_string:
        return False, "BOOLEAN_TAUTOLOGY"

    normalized = re.sub(r"\s+", " ", "".join(output)).strip().lower()

    if re.search(
        r"\b(?:pg_sleep|benchmark)\s*\(|\bwaitfor\s+delay\b",
        normalized,
        flags=re.IGNORECASE,
    ):
        return False, "TIME_BASED_EXECUTION"

    if re.search(
        r";\s*(?:drop\b|delete\s+from\b|exec(?:ute)?\b)",
        normalized,
        flags=re.IGNORECASE,
    ):
        return False, "STACKED_QUERY"

    if re.search(
        r"\bunion\s+(?:(?:all|distinct)\s+)?select\b",
        normalized,
        flags=re.IGNORECASE,
    ):
        return False, "UNION_EXFILTRATION"

    literal_or_number = r"(?:__str_\d+__|\d+(?:\.\d+)?|true|false)"
    tautology_pattern = re.compile(
        rf"\bor\b\s*\(?\s*({literal_or_number})\s*=\s*({literal_or_number})",
        flags=re.IGNORECASE,
    )

    for match in tautology_pattern.finditer(normalized):
        left, right = match.group(1), match.group(2)

        def value_of(token: str) -> str:
            return string_values.get(token, token.lower())

        if value_of(left) == value_of(right):
            return False, "BOOLEAN_TAUTOLOGY"

    return True, "SAFE"
