import threading
from collections import deque


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than 0")
        if ping_timeout <= 0:
            raise ValueError("ping_timeout must be greater than 0")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._next_id = 1
        self._closed = False
        self._available = deque()
        self._leased = {}

        for _ in range(max_connections):
            self._available.append(self._create_connection())

    def _create_connection(self) -> dict:
        connection = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return connection

    def acquire(self) -> dict:
        with self._lock:
            if self._closed or not self._available:
                raise RuntimeError("Pool exhausted")

            conn = self._available.popleft()
            self._leased[id(conn)] = conn
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            if id(conn) not in self._leased:
                raise ValueError("Connection does not belong to this pool or is already released")

            self._leased.pop(id(conn))

            if not self._closed:
                self._available.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            if self._closed:
                return 0

            healed = 0
            connections = list(self._available) + list(self._leased.values())

            for conn in connections:
                if not conn.get("alive", False):
                    conn.clear()
                    conn.update(self._create_connection())
                    healed += 1

            return healed

    def close_all(self) -> None:
        with self._lock:
            self._available.clear()
            self._leased.clear()
            self._closed = True
