def prune_dead_code_and_imports(source_code: str) -> str:
    import ast

    tree = ast.parse(source_code)

    used_names = {
        node.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
    }

    private_functions = {
        node.name
        for node in tree.body
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
        and node.name.startswith("_")
        and node.name not in used_names
    }

    class DeadCodePruner(ast.NodeTransformer):
        def visit_Import(self, node):
            kept = [
                alias
                for alias in node.names
                if (alias.asname or alias.name.split(".")[0]) in used_names
            ]
            if not kept:
                return None
            node.names = kept
            return node

        def visit_ImportFrom(self, node):
            if any(alias.name == "*" for alias in node.names):
                return node

            kept = [
                alias
                for alias in node.names
                if (alias.asname or alias.name) in used_names
            ]
            if not kept:
                return None
            node.names = kept
            return node

    pruner = DeadCodePruner()
    tree = pruner.visit(tree)
    tree.body = [
        node
        for node in tree.body
        if not (
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name in private_functions
        )
    ]

    ast.fix_missing_locations(tree)
    result = ast.unparse(tree)
    compile(result, "<pruned>", "exec")
    return result + "\n"
