class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        tasks = set(dependencies)
        for prerequisites in dependencies.values():
            tasks.update(prerequisites)

        dependents: dict[str, set[str]] = {task: set() for task in tasks}
        remaining: dict[str, int] = {task: 0 for task in tasks}

        for task, prerequisites in dependencies.items():
            unique_prerequisites = set(prerequisites)
            remaining[task] = len(unique_prerequisites)

            for prerequisite in unique_prerequisites:
                dependents[prerequisite].add(task)

        stages: list[list[str]] = []
        ready = sorted(task for task in tasks if remaining[task] == 0)
        processed = 0

        while ready:
            stage = ready
            stages.append(stage)
            processed += len(stage)

            next_ready: set[str] = set()
            for task in stage:
                for dependent in dependents[task]:
                    remaining[dependent] -= 1
                    if remaining[dependent] == 0:
                        next_ready.add(dependent)

            ready = sorted(next_ready)

        if processed != len(tasks):
            raise CircularDependencyError("Circular dependency detected")

        return stages
