from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if not node_ids:
            raise ValueError("node_ids must not be empty")
        if len(set(node_ids)) != len(node_ids):
            raise ValueError("node_ids must be unique")

        self.node_ids = list(node_ids)
        self.total_nodes = len(node_ids)
        self.quorum_threshold = self.total_nodes // 2 + 1

        self._state_by_node: dict[str, dict[str, Any]] = {
            node_id: {} for node_id in self.node_ids
        }
        self._partitions: list[set[str]] = [set(self.node_ids)]

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        group_a_set = set(group_a)
        group_b_set = set(group_b)
        cluster_nodes = set(self.node_ids)

        if len(group_a_set) != len(group_a) or len(group_b_set) != len(group_b):
            raise ValueError("Partition groups must not contain duplicate nodes")
        if group_a_set & group_b_set:
            raise ValueError("Partition groups must be disjoint")
        if group_a_set | group_b_set != cluster_nodes:
            raise ValueError("Partition groups must contain every cluster node")
        if not group_a_set or not group_b_set:
            raise ValueError("Partition groups must both be non-empty")

        self._partitions = [group_a_set, group_b_set]

    def heal_partition(self) -> None:
        if len(self._partitions) == 1:
            return

        majority_partition = max(self._partitions, key=len)
        if len(majority_partition) < self.quorum_threshold:
            raise RuntimeError("No partition has a quorum")

        source_node = next(iter(majority_partition))
        committed_state = dict(self._state_by_node[source_node])

        for node_id in self.node_ids:
            self._state_by_node[node_id] = dict(committed_state)

        self._partitions = [set(self.node_ids)]

    def propose_write(
        self,
        from_node: str,
        key: str,
        value: Any,
    ) -> bool:
        if from_node not in self._state_by_node:
            raise ValueError(f"Unknown node: {from_node}")

        active_partition = next(
            partition
            for partition in self._partitions
            if from_node in partition
        )

        if len(active_partition) < self.quorum_threshold:
            return False

        for node_id in active_partition:
            self._state_by_node[node_id][key] = value

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self._state_by_node:
            raise ValueError(f"Unknown node: {from_node}")

        return self._state_by_node[from_node].get(key)
