def parse_markdown_links(text: str) -> list[dict[str, str]]:
    """Extract markdown links in guaranteed linear time."""
    results: list[dict[str, str]] = []
    n = len(text)
    i = 0

    def is_title_char(char: str) -> bool:
        return (
            "a" <= char <= "z"
            or "A" <= char <= "Z"
            or "0" <= char <= "9"
            or char in {" ", "_"}
        )

    while i < n:
        if text[i] != "[":
            i += 1
            continue

        title_start = i + 1
        j = title_start

        while j < n and is_title_char(text[j]):
            j += 1

        if j == title_start or j >= n or text[j] != "]":
            i += 1
            continue

        if j + 1 >= n or text[j + 1] != "(":
            i += 1
            continue

        url_start = j + 2
        if text.startswith("https://", url_start):
            scheme_end = url_start + 8
        elif text.startswith("http://", url_start):
            scheme_end = url_start + 7
        else:
            i += 1
            continue

        k = scheme_end
        while k < n and text[k] not in " \t\r\n)":
            k += 1

        if k < n and text[k] == ")" and k > scheme_end:
            results.append({
                "title": text[title_start:j],
                "url": text[url_start:k],
            })
            i = k + 1
        elif k >= n:
            break
        else:
            i = k

    return results
