from collections import deque
from threading import RLock


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if not isinstance(max_connections, int) or isinstance(max_connections, bool):
            raise TypeError("max_connections must be an int")
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than zero")
        if ping_timeout < 0:
            raise ValueError("ping_timeout must not be negative")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._next_id = 1
        self._connections = {}
        self._available = deque()
        self._in_use = set()
        self._lock = RLock()

        for _ in range(max_connections):
            conn = self._new_connection()
            self._connections[conn["id"]] = conn
            self._available.append(conn)

    def _new_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if not self._available:
                raise RuntimeError("Pool exhausted")

            conn = self._available.popleft()
            self._in_use.add(conn["id"])
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            if not isinstance(conn, dict) or "id" not in conn:
                raise ValueError("Invalid connection")

            connection_id = conn["id"]
            tracked = self._connections.get(connection_id)

            if tracked is not conn:
                raise ValueError("Connection does not belong to this pool")
            if connection_id not in self._in_use:
                raise RuntimeError("Connection was not acquired")

            self._in_use.remove(connection_id)
            self._available.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            healed = 0

            for old_id, conn in list(self._connections.items()):
                if conn.get("alive") is False:
                    was_in_use = old_id in self._in_use
                    new_conn = self._new_connection()

                    conn.clear()
                    conn.update(new_conn)

                    del self._connections[old_id]
                    self._connections[conn["id"]] = conn

                    if was_in_use:
                        self._in_use.remove(old_id)
                        self._in_use.add(conn["id"])

                    healed += 1

            return healed

    def close_all(self) -> None:
        with self._lock:
            for conn in self._connections.values():
                conn["alive"] = False

            self._connections.clear()
            self._available.clear()
            self._in_use.clear()
