def prune_dead_code_and_imports(source_code: str) -> str:
    import ast

    tree = ast.parse(source_code)

    def load_names(node):
        return {
            child.id
            for child in ast.walk(node)
            if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Load)
        }

    # Remove unreferenced top-level private functions.
    referenced_names = load_names(tree)
    tree.body = [
        node
        for node in tree.body
        if not (
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name.startswith("_")
            and node.name not in referenced_names
        )
    ]

    # Recalculate references after removing dead functions.
    referenced_names = load_names(tree)
    new_body = []

    for node in tree.body:
        if isinstance(node, ast.Import):
            kept_aliases = [
                alias
                for alias in node.names
                if (alias.asname or alias.name.split(".")[0]) in referenced_names
            ]
            if kept_aliases:
                node.names = kept_aliases
                new_body.append(node)

        elif isinstance(node, ast.ImportFrom):
            if node.module == "__future__":
                new_body.append(node)
                continue

            kept_aliases = [
                alias
                for alias in node.names
                if alias.name == "*"
                or (alias.asname or alias.name) in referenced_names
            ]
            if kept_aliases:
                node.names = kept_aliases
                new_body.append(node)

        else:
            new_body.append(node)

    tree.body = new_body
    ast.fix_missing_locations(tree)
    return ast.unparse(tree)
